scripts.杨瑛的同伴对话.txt:
// 和杨瑛对话

	If ($Event == 580) @Event580;
	If ($Event == 600) @Event600;
	If ($Event == 605) @Event605;
	If ($Event == 610) @Event610;
	
@Event580:
	PlayerGoto(15, 38);
	SetPlayerDir(4);
	SetNpcDir("杨瑛", 0);
	Say("杨瑛：独孤掌门，你来了。", 34);
	Say("独孤剑：帮主！适才……", 1);
	Say("杨瑛：不必说了……嗯，王前使有何事要公子转达？", 34);
	Say("独孤剑：王将军想恳请帮主与岳元帅尽释前嫌，并希望帮主能将“山河社稷图”交给元帅，帮助岳帅完成收复中原的大业。", 1);
	Say("杨瑛：……独孤掌门，在下倒有个疑问一直想请教。", 34);
	Say("独孤剑：帮主请问。", 1);
	Say("杨瑛：当日，倘若张风当真是害死令尊的凶手，独孤掌门会因为——张姑娘，而放下这杀父之仇吗？", 34);
	Say("独孤剑：……帮主，当日独孤剑自不量力，要杀张世伯，是因为误会他是一个投敌卖国、卖友求荣的卑鄙小人，而非仅仅是为报杀父之仇。", 1);
	Say("杨瑛：……", 36);
	Say("独孤剑：及至误会消除，独孤剑对张世伯只有敬佩之情。如今，岳元帅乃大宋之栋梁，肩负驱除鞑虏，收复河山的大任。为国为民，都望帮主能暂时放下个人的恩怨……", 1);
	Say("杨瑛：金国又如何？大宋又如何？背井离乡、妻离子散的还不是这些穷苦百姓！谁做皇帝，不是为一己之私！", 34);
	Say("独孤剑：独孤剑乃一介莽夫，实不解其中原委。不过，在下知道，若要独孤剑加害一个堂堂正正、光明磊落的英雄好汉，便是万万不能！", 1);
	Say("杨瑛：……王前使为了岳飞，真的甘愿自断一臂？……", 36);
	Say("独孤剑：王将军乃忠义之士，决没有背叛帮主之意！只是将军为岳元帅精忠报国的气概所感动，所以……", 1);
	Say("杨瑛：我倒想亲眼见见这个大英雄、大好汉……至于“山河社稷图”，那是本帮弟兄花了很大力气才得到的，事关重大，给不给岳飞，还要等我与帮中弟兄商量之后方可决定。", 34);
	Say("独孤剑：杨帮主少年英雄，胸怀坦荡，令人佩服！今日能够结识杨帮主，在下实在是三生有幸！如蒙帮主不弃，我想与你二人结拜为八拜之交，不知帮主意下如何？", 2);
	Say("杨瑛：这……", 36);
	Say("独孤剑：怎么？莫非帮主嫌弃……", 8);
	Say("杨瑛：不，不是的……", 36);
	Say("独孤剑：那……", 8);
	Sleep(200);
	Say("独孤剑：小心！", 6);
	Say("杨瑛：啊！……", 36);

	
	DelNpc("杨瑛");//扑到在地
	SetNpcActionFile("独孤剑", 0, "mpc046_2.asf");
	SetNpcActionFile("独孤剑", 1, "mpc046_2.asf");
	NpcSpecialAction("独孤剑", "mpc046_1.asf");
	Sleep(800);
	PlaySound("魔-爆07.wav");
	AddObj("一团火球.ini", 15, 37, 0);
	Sleep(1000);
	DelObj("一团火球");
	Sleep(2500);
	
	FadeOut();
	SetNpcActionFile("独孤剑", 0, "npc001_st2.asf");
	SetNpcActionFile("独孤剑", 1, "npc001_sst2.asf");
	PlayerGoto(15, 38);
	SetPlayerDir(3);
	AddNpc("npc007_男装披发的杨瑛.ini", 14, 37, 7);
	Say("一股从未体验过的气息沁入独孤剑的心脾，独孤剑如痴如醉，呆呆地和杨瑛对视了好一会儿，二人才回过神来……");
	FadeIn();
	
	Say("独孤剑：杨帮主，你……你没事吧？……", 4);
	Say("杨瑛：……", 38);
	Say("独孤剑：在下唐突，冒犯姑娘，请姑娘恕罪……在下实在是不知……", 4);
	Say("杨瑛：……", 38);
	
	Say("杨湖：帮主！出什么事了！", 100);
	AddNpc("npc025_杨湖.ini", 12, 56, 4);
	AddNpc("npc083_路云远.ini", 13, 56, 4);
	NpcGotoEx("杨湖", 14, 38);
	NpcGoto("路云远", 12, 45);
	NpcGoto("路云远", 14, 39);
	Sleep(200);
	SetNpcDir("杨湖", 5);
	SetNpcDir("路云远", 4);
	Say("杨湖：帮主，你……", 100);
	Say("杨瑛：我……我没事。", 38);
	NpcGoto("杨瑛", 9, 36);
	DelNpc("杨瑛");
	Sleep(300);	
	Watch("杨湖", "独孤剑", 0);
	Say("杨湖：独孤兄弟，发生了什么事？我们好像听见了火弹爆炸的声音。"， 100);
	Say("独孤剑：适才有人偷袭，所以……", 4);
	Say("路云远：岂有此理，竟会发生这种事！", 0);
	Say("杨湖：噫——封左使呢？", 100);
	Say("路云远：莫非有人混上岛了？", 0);
	Sleep(500);
	
	AddNpc("npc102_天王帮众.ini", 12, 56, 4);
	NpcGoto("天王帮众", 13, 41);
	SetNpcDir("天王帮众", 5);
	SetNpcDir("杨湖", 1);
	SetNpcDir("路云远", 2);
	SetPlayerDir(1);
	Say("“雾里金刚”宋千：禀告护法、杨右使！外面粮仓、船坞等处走水，弟兄们正在抢救。");
	Say("杨湖：有没有见到封左使？", 100);
	Say("“雾里金刚”宋千：封左使刚才带着一帮弟兄到后殿搜查去了。");
	Say("路云远：杨右使，走，我们出去看看！");
	Say("杨湖：好！", 100);
	Watch("杨湖", "独孤剑", 0);
	Say("杨湖：独孤兄弟，还不快去看看帮主……", 100);
	Sleep(500);
	NpcGotoEx("天王帮众", 12, 56);
	NpcGotoEx("路云远", 13, 56);
	NpcGoto("杨湖", 12, 55);
	Sleep(500);
	DelNpc("天王帮众");
	DelNpc("路云远");
	DelNpc("杨湖");
	AddNpc("npc008_杨瑛.ini", 13, 11, 5);
	SaveNpc();
	SetNpcScript("杨瑛", "杨瑛的同伴对话.txt");
	SetNpcDeathScript("杨瑛", "主角死亡.txt");
	Assign($Event, 600);
	SetMapTrap(1, "trap01.txt");
	Memo("独孤剑来到后花园，见到杨瑛，二人正谈得投机，突然有人偷袭，独孤剑一跃将杨瑛扑倒在地，意外发现杨瑛竟是个女子！杨瑛含羞离开，杨湖建议独孤剑去向帮主解释清楚。");
	Return;
	
@Event600:
	Say("独孤剑：杨帮主，适才……", 4);
	Say("杨瑛：适才，独孤公子救了我，杨瑛欠你一份情。", 40);
	Say("独孤剑：在下实在……", 4);
	Say("杨瑛：独孤公子，你觉得这里美吗？", 39);
	NpcGoto("杨瑛", 14, 10);
	SetNpcDir("杨瑛", 5);
	PlayerGoto(13, 9);
	SetPlayerDir(5);
	Say("独孤剑：这里湖中有岛，岛中有湖，仿佛人间仙境……", 2);
	Sleep(500);
	Say("杨瑛：从小，父王就把我当成男孩子来养，这件事，只有路护法等少数几个帮中的前辈知道……这么多年来，我一直隐藏自己的身份，唯恐帮中的弟兄知道带着他们冒性命之危闯荡江湖的，竟是一个弱质女流……", 41);
	Say("独孤剑：……", 1);
	Say("杨瑛：白天，我是一个高高在上的帮主；到晚上，我只是一个和萍儿莺儿相依为命的弱女子……只有在这里，我才真正地感到开心……", 41);
	Say("杨瑛：独孤公子也看到了，现在帮中矛盾重重，封左使执意要用帮规处置王叔叔，路伯伯又渐渐不管帮中的事务……", 41);
	SetPlayerDir(7);
	Say("独孤剑：帮主虽然是女子，但我听王将军说过，帮主胆识过人，顾识大体，没有帮主，就不会有天王帮。", 2);
	Say("杨瑛：……其实，我很羡慕寻常老百姓那种平平凡凡、自由自在的生活……", 39);
	SetNpcDir("杨瑛", 3);
	Say("杨瑛：独孤公子，你刚才说，这里是人间仙境，不如公子就留在这多住几日？", 39);
	Say("独孤剑：这……多谢帮主美意，只是独孤剑尚有同伴在外等候，实在不便久留……只希望帮主能够化解与岳元帅的这段恩怨，将“山河图”交给岳帅。", 2);
	Say("杨瑛：如果我不愿交给岳飞呢？", 39);
	Say("独孤剑：这，就算在下求帮主……", 1);

	Say("杨瑛：岳飞不只和我有杀父之仇，更欠天王帮数万条性命，我可以不和他计较恩怨，但你教我如何面对帮中的数千兄弟！", 39);
	Say("独孤剑：欠下这些血债的是朝廷，不是岳家军，岳元帅也是身不由己……", 1);
	Say("杨瑛：独孤公子，我不愿将图交给岳飞，但是我欠你一个人情，既然是你要我交出“山河社稷图”，那我就交给公子。", 39);
	Say("独孤剑：帮主……", 8);
	Say("杨瑛：图就在我房间里，随我去取吧！", 39);
	SetNpcKind("杨瑛", 3);
	SetNpcRelation("杨瑛", 0);
	Assign($Event, 605);
	SetMapTrap(1, "trap01.txt");
	Memo("杨瑛终于答应交出地图，但依然不肯化解和岳飞的仇怨，只答应将地图交给独孤剑，两人前往寝宫去取“山河社稷图”。");
	Return;
	
@Event605:	
	Say("杨瑛：图就在我房间里，随我去取吧！", 39);
	Return;
	
@Event610:		
	Say("杨瑛：我们走吧。", 39);
	Return;

traps.trap01.txt:
// 切换到map101天王帮大殿

	If ($Event == 580) @Event580;
	If ($Event == 600) @Event600;
	If ($Event == 605) @Event605;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map101_天王帮大殿.map");
	LoadNpc("map101.npc");
	LoadObj("map101.obj");
	SetPlayerPos(13, 15);
	SetPlayerDir(7);
	FadeIn();
	Return;

@Event580:
	Say("独孤剑：杨帮主还在后花园等我呢。", 1);
	Return;

@Event600:
	Say("独孤剑：去向杨帮……杨姑娘解释清楚吧。", 4);
	Return;
		
@Event605:
	Say("杨瑛：独孤公子，这是去大殿的路。", 39);
	Return;

traps.trap02.txt:
// 切换到map103杨瑛寝宫

	If ($Event == 605) @Event605;
	
	FadeOut();
	SaveNpc();
	SaveObj();
	LoadMap("map103_杨瑛寝宫.map");
	LoadNpc("map103.npc");
	LoadObj("map103.obj");
	SetPlayerPos(13, 39);
	SetPlayerDir(3);
	FadeIn();
	Return;
	
@Event605:
	FadeOut();
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("杀机.mp3");
	LoadMap("map103_杨瑛寝宫.map");
	LoadNpc("map103.npc");
	LoadObj("map103.obj");
	DelNpc("萍儿");
	DelNpc("莺儿");
	AddNpc("npc026_封玉书冒烟.ini", 6, 28, 5);
	SetPlayerPos(13, 39);
	SetPlayerDir(3);
	FadeIn();
	Say("杨瑛：萍儿！莺儿！咦？人都到哪里去了？", 39);
	SetMapTrap(2, "trap02.txt");
	Return;
